catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

	var ga = new GlideAjax('PEAR_Utils3');
	ga.addParam('sysparm_name', 'isProjectRequiredByBusinessProfile');
	// ga.addParam('sysparm_name', 'getProjectsByBusinessProfile');
    ga.addParam('sysparm_BusinessProfileId', newValue);
    ga.getXMLAnswer(function(answer) {
		var isRequired = (answer === 'true');
		if(isRequired==true)
		{
			// g_form.addInfoMessage('isRequired è true')
			// g_form.setVisible('projects_mrvs', true);
			g_form.setMandatory('projects_mrvs', true);
		}
		else
		{
			// g_form.addInfoMessage('isRequired è false')
			// g_form.setVisible('projects_mrvs',  false);
			g_form.setMandatory('projects_mrvs', false);
		}

    });


   //Type appropriate comment here, and begin script below

}
